INSERT INTO `mdl_block_configurable_reports` (`id`, `courseid`, `ownerid`, `visible`, `name`, `summary`, `summaryformat`, `type`, `pagination`, `components`, `export`, `jsordering`, `global`, `lastexecutiontime`, `cron`, `remote`, `displaytotalrecords`, `displayprintbutton`) VALUES
(1, 1, 2, 1, 'Total Employees', '<div>Displays total active employees in the LMS.</div>', 1, 'sql', 0, 'a:2:{i:0;b:0;s:9:\"customsql\";a:1:{s:6:\"config\";O:8:\"stdClass\":6:{s:8:\"querysql\";s:62:\"SELECT+COUNT%28%2A%29+AS+Total_Employees%0D%0AFROM+prefix_user\";s:8:\"courseid\";i:1;s:12:\"submitbutton\";s:12:\"Save+changes\";s:16:\"reportcategories\";s:1:\"0\";s:17:\"reportsincategory\";s:1:\"0\";s:14:\"remotequerysql\";s:0:\"\";}}}', 'csv,', 1, 1, 1, 0, 0, 0, 0),
(2, 1, 2, 1, 'Course Enrollment Analytics', '', 1, 'sql', 0, 'a:3:{i:0;b:0;s:9:\"customsql\";a:1:{s:6:\"config\";O:8:\"stdClass\":6:{s:8:\"querysql\";s:271:\"SELECT%0D%0Ac.fullname+AS+Course%2C%0D%0ACOUNT%28ue.userid%29+AS+Enrolled_Users%0D%0AFROM+prefix_course+c%0D%0AJOIN+prefix_enrol+e+ON+e.courseid+%3D+c.id%0D%0AJOIN+prefix_user_enrolments+ue+ON+ue.enrolid+%3D+e.id%0D%0AGROUP+BY+c.fullname%0D%0AORDER+BY+Enrolled_Users+DESC\";s:8:\"courseid\";i:1;s:12:\"submitbutton\";s:12:\"Save+changes\";s:16:\"reportcategories\";s:1:\"0\";s:17:\"reportsincategory\";s:1:\"0\";s:14:\"remotequerysql\";s:0:\"\";}}s:4:\"plot\";a:1:{s:8:\"elements\";a:1:{i:0;a:5:{s:2:\"id\";s:15:\"dMWcYRKIZ430Baj\";s:8:\"formdata\";O:8:\"stdClass\":5:{s:11:\"label_field\";s:10:\"0%2Ccourse\";s:12:\"value_fields\";a:1:{i:0;s:18:\"1%2Cenrolled_users\";}s:5:\"width\";i:900;s:6:\"height\";i:500;s:12:\"submitbutton\";s:3:\"Add\";}s:10:\"pluginname\";s:3:\"bar\";s:14:\"pluginfullname\";s:9:\"Bar+chart\";s:7:\"summary\";s:17:\"Bar+chart+summary\";}}}}', 'csv,', 1, 1, 2, 0, 0, 0, 0);
