(1873, 2, 1792594702, 'theme_boost', 'scss', 'body {\r\n    background: #f4f7fb;\r\n}\r\n\r\n.main-inner {\r\n    background: #ffffff;\r\n    border-radius: 16px;\r\n    padding: 20px;\r\n    box-shadow: 0 4px 12px rgba(0,0,0,.08);\r\n}\r\n\r\n.activity-item {\r\n    border-radius: 12px;\r\n    border: 1px solid #e3e6ea;\r\n    margin-bottom: 15px;\r\n}\r\n\r\n.navbar {\r\n    background: #0F4C81 !important;\r\n}\r\n\r\n.btn-primary {\r\n    background: #0F4C81 !important;\r\n    border-color: #0F4C81 !important;\r\n}\r\n\r\nh1,h2,h3 {\r\n    color: #0F4C81;\r\n}\r\n\r\n\r\n/* Fix Site Administration category tiles */\r\n\r\n.adminexternalpage .categoryname,\r\n.adminsettings .categoryname,\r\n#page-admin-index .card-title,\r\n#page-admin-index .category {\r\n    color: #0F4C81 !important;\r\n    font-weight: 600;\r\n}\r\n\r\n/* Make administration cards visible */\r\n.adminindex .card,\r\n.path-admin .card {\r\n    background: #ffffff !important;\r\n    color: #0F4C81 !important;\r\n}\r\n\r\n/* Category icon text */\r\n.adminindex .admintree .tree_item,\r\n.path-admin .tree_item {\r\n    color: #0F4C81 !important;\r\n}\r\n/* VKollab Navbar */\r\n\r\n.navbar {\r\n    background: #0F4C81 !important;\r\n}\r\n\r\n/* All navbar links */\r\n.primary-navigation .navigation .nav-link,\r\n.moremenu .nav-link,\r\n.navbar-nav .nav-link,\r\n.navbar-brand {\r\n    color: #ffffff !important;\r\n    font-weight: 600 !important;\r\n}\r\n\r\n/* Hover effect */\r\n.primary-navigation .navigation .nav-link:hover,\r\n.moremenu .nav-link:hover,\r\n.navbar-nav .nav-link:hover {\r\n    color: #ffffff !important;\r\n    background: rgba(255,255,255,0.15) !important;\r\n    border-radius: 6px;\r\n}\r\n\r\n/* Active tab */\r\n.primary-navigation .navigation .nav-link.active,\r\n.moremenu .nav-link.active {\r\n    color: #ffffff !important;\r\n    background: rgba(255,255,255,0.20) !important;\r\n    border-radius: 6px;\r\n}\r\n\r\n/* Icons */\r\n.navbar i,\r\n.navbar .icon {\r\n    color: white !important;\r\n}\r\n\r\n/* User menu */\r\n.usermenu *,\r\n.langmenu * {\r\n    color: white !important;\r\n}\r\n\r\n/* Notification icons */\r\n.popover-region-toggle {\r\n    color: white !important;\r\n}\r\n\r\n/* Edit mode text */\r\n.editmode-switch-form label {\r\n    color: white !important;\r\n}\r\n\r\n', 'body {\r\n    background: #f4f7fb;\r\n}\r\n\r\n.main-inner {\r\n    background: #ffffff;\r\n    border-radius: 16px;\r\n    padding: 20px;\r\n    box-shadow: 0 4px 12px rgba(0,0,0,.08);\r\n}\r\n\r\n.activity-item {\r\n    border-radius: 12px;\r\n    border: 1px solid #e3e6ea;\r\n    margin-bottom: 15px;\r\n}\r\n\r\n.navbar {\r\n    background: #0F4C81 !important;\r\n}\r\n\r\n.btn-primary {\r\n    background: #0F4C81 !important;\r\n    border-color: #0F4C81 !important;\r\n}\r\n\r\nh1,h2,h3 {\r\n    color: #0F4C81;\r\n}\r\n\r\n\r\n/* Fix Site Administration category tiles */\r\n\r\n.adminexternalpage .categoryname,\r\n.adminsettings .categoryname,\r\n#page-admin-index .card-title,\r\n#page-admin-index .category {\r\n    color: #0F4C81 !important;\r\n    font-weight: 600;\r\n}\r\n\r\n/* Make administration cards visible */\r\n.adminindex .card,\r\n.path-admin .card {\r\n    background: #ffffff !important;\r\n    color: #0F4C81 !important;\r\n}\r\n\r\n/* Category icon text */\r\n.adminindex .admintree .tree_item,\r\n.path-admin .tree_item {\r\n    color: #0F4C81 !important;\r\n}\r\n'),
(1874, 2, 1792594808, 'theme_boost', 'scss', '/* ==========================================\r\n   VKOLLAB LMS CORPORATE THEME\r\n   ========================================== */\r\n\r\n/* Page Background */\r\nbody {\r\n    background: #f4f7fb !important;\r\n}\r\n\r\n/* Main Content Container */\r\n.main-inner {\r\n    background: #ffffff;\r\n    border-radius: 16px;\r\n    padding: 20px;\r\n    box-shadow: 0 4px 12px rgba(0,0,0,.08);\r\n}\r\n\r\n/* ==========================================\r\n   NAVIGATION BAR\r\n   ========================================== */\r\n\r\n.navbar {\r\n    background: #0F4C81 !important;\r\n    border-bottom: none !important;\r\n}\r\n\r\n.navbar-brand,\r\n.navbar .nav-link,\r\n.primary-navigation .navigation .nav-link,\r\n.moremenu .nav-link {\r\n    color: #ffffff !important;\r\n    font-weight: 600;\r\n}\r\n\r\n/* Active Menu */\r\n.navbar .nav-link.active,\r\n.moremenu .nav-link.active,\r\n.primary-navigation .navigation .nav-link.active {\r\n    color: #ffffff !important;\r\n    background: rgba(255,255,255,.15) !important;\r\n    border-radius: 6px;\r\n}\r\n\r\n/* Hover */\r\n.navbar .nav-link:hover,\r\n.moremenu .nav-link:hover,\r\n.primary-navigation .navigation .nav-link:hover {\r\n    color: #ffffff !important;\r\n    background: rgba(255,255,255,.10) !important;\r\n    border-radius: 6px;\r\n}\r\n\r\n/* Icons */\r\n.navbar i,\r\n.navbar .icon,\r\n.popover-region-toggle {\r\n    color: #ffffff !important;\r\n}\r\n\r\n/* User Menu */\r\n.usermenu *,\r\n.langmenu * {\r\n    color: #ffffff !important;\r\n}\r\n\r\n/* Edit Mode */\r\n.editmode-switch-form label {\r\n    color: #ffffff !important;\r\n}\r\n\r\n/* ==========================================\r\n   COURSE CARDS\r\n   ========================================== */\r\n\r\n.coursebox,\r\n.card,\r\n.block {\r\n    border-radius: 12px;\r\n    border: none !important;\r\n    box-shadow: 0 4px 12px rgba(0,0,0,.08);\r\n    background: #ffffff;\r\n}\r\n\r\n/* ==========================================\r\n   HEADINGS\r\n   ========================================== */\r\n\r\nh1 {\r\n    color: #0F4C81 !important;\r\n    font-weight: 700;\r\n}\r\n\r\nh2 {\r\n    color: #1D70B8 !important;\r\n    font-weight: 600;\r\n}\r\n\r\nh3 {\r\n    color: #0F4C81 !important;\r\n}\r\n\r\n/* ==========================================\r\n   LINKS\r\n   ========================================== */\r\n\r\na {\r\n    color: #1D70B8;\r\n}\r\n\r\na:hover {\r\n    color: #0F4C81;\r\n}\r\n\r\n/* ==========================================\r\n   BUTTONS\r\n   ========================================== */\r\n\r\n.btn-primary {\r\n    background: #0F4C81 !important;\r\n    border-color: #0F4C81 !important;\r\n    border-radius: 8px;\r\n}\r\n\r\n.btn-primary:hover {\r\n    background: #1D70B8 !important;\r\n    border-color: #1D70B8 !important;\r\n}\r\n\r\n/* ==========================================\r\n   DASHBOARD BLOCKS\r\n   ========================================== */\r\n\r\n.block {\r\n    padding: 10px;\r\n}\r\n\r\n/* ==========================================\r\n   SITE ADMINISTRATION PAGE FIX\r\n   ========================================== */\r\n\r\n#page-admin-index .card,\r\n.path-admin .card {\r\n    background: #ffffff !important;\r\n    color: #0F4C81 !important;\r\n    border-radius: 12px;\r\n}\r\n\r\n/* Administration Category Titles */\r\n#page-admin-index .category,\r\n#page-admin-index .card-title,\r\n.path-admin .card-title {\r\n    color: #0F4C81 !important;\r\n    font-weight: 600 !important;\r\n}\r\n\r\n/* Administration Links */\r\n#page-admin-index a,\r\n.path-admin a {\r\n    color: #1D70B8 !important;\r\n}\r\n\r\n/* ==========================================\r\n   ACTIVITY SECTIONS\r\n   ========================================== */\r\n\r\n.activity-item {\r\n    margin-bottom: 15px;\r\n    padding: 15px;\r\n    border-radius: 10px;\r\n    background: #ffffff;\r\n    border: 1px solid #e5e7eb;\r\n}\r\n\r\n/* ==========================================\r\n   TABLES\r\n   ========================================== */\r\n\r\n.generaltable {\r\n    border-radius: 8px;\r\n    overflow: hidden;\r\n}\r\n\r\n.generaltable th {\r\n    background: #0F4C81 !important;\r\n    color: white !important;\r\n}\r\n\r\n/* ==========================================\r\n   FOOTER\r\n   ========================================== */\r\n\r\n#page-footer {\r\n    background: #0F4C81;\r\n    color: #ffffff;\r\n    padding: 15px;\r\n}\r\n\r\n/* ==========================================\r\n   CUSTOM HOMEPAGE BANNER\r\n   ========================================== */\r\n\r\n.vk-banner {\r\n    background: linear-gradient(135deg,#0F4C81,#1D70B8);\r\n    color: white;\r\n    padding: 50px;\r\n    border-radius: 16px;\r\n    text-align: center;\r\n    margin-bottom: 20px;\r\n}\r\n\r\n.vk-banner h1 {\r\n    color: #ffffff !important;\r\n}\r\n\r\n.vk-banner p {\r\n    color: #ffffff !important;\r\n    font-size: 18px;\r\n}', 'body {\r\n    background: #f4f7fb;\r\n}\r\n\r\n.main-inner {\r\n    background: #ffffff;\r\n    border-radius: 16px;\r\n    padding: 20px;\r\n    box-shadow: 0 4px 12px rgba(0,0,0,.08);\r\n}\r\n\r\n.activity-item {\r\n    border-radius: 12px;\r\n    border: 1px solid #e3e6ea;\r\n    margin-bottom: 15px;\r\n}\r\n\r\n.navbar {\r\n    background: #0F4C81 !important;\r\n}\r\n\r\n.btn-primary {\r\n    background: #0F4C81 !important;\r\n    border-color: #0F4C81 !important;\r\n}\r\n\r\nh1,h2,h3 {\r\n    color: #0F4C81;\r\n}\r\n\r\n\r\n/* Fix Site Administration category tiles */\r\n\r\n.adminexternalpage .categoryname,\r\n.adminsettings .categoryname,\r\n#page-admin-index .card-title,\r\n#page-admin-index .category {\r\n    color: #0F4C81 !important;\r\n    font-weight: 600;\r\n}\r\n\r\n/* Make administration cards visible */\r\n.adminindex .card,\r\n.path-admin .card {\r\n    background: #ffffff !important;\r\n    color: #0F4C81 !important;\r\n}\r\n\r\n/* Category icon text */\r\n.adminindex .admintree .tree_item,\r\n.path-admin .tree_item {\r\n    color: #0F4C81 !important;\r\n}\r\n/* VKollab Navbar */\r\n\r\n.navbar {\r\n    background: #0F4C81 !important;\r\n}\r\n\r\n/* All navbar links */\r\n.primary-navigation .navigation .nav-link,\r\n.moremenu .nav-link,\r\n.navbar-nav .nav-link,\r\n.navbar-brand {\r\n    color: #ffffff !important;\r\n    font-weight: 600 !important;\r\n}\r\n\r\n/* Hover effect */\r\n.primary-navigation .navigation .nav-link:hover,\r\n.moremenu .nav-link:hover,\r\n.navbar-nav .nav-link:hover {\r\n    color: #ffffff !important;\r\n    background: rgba(255,255,255,0.15) !important;\r\n    border-radius: 6px;\r\n}\r\n\r\n/* Active tab */\r\n.primary-navigation .navigation .nav-link.active,\r\n.moremenu .nav-link.active {\r\n    color: #ffffff !important;\r\n    background: rgba(255,255,255,0.20) !important;\r\n    border-radius: 6px;\r\n}\r\n\r\n/* Icons */\r\n.navbar i,\r\n.navbar .icon {\r\n    color: white !important;\r\n}\r\n\r\n/* User menu */\r\n.usermenu *,\r\n.langmenu * {\r\n    color: white !important;\r\n}\r\n\r\n/* Notification icons */\r\n.popover-region-toggle {\r\n    color: white !important;\r\n}\r\n\r\n/* Edit mode text */\r\n.editmode-switch-form label {\r\n    color: white !important;\r\n}\r\n\r\n'),
