n}\r\n\r\n.main-inner{\r\n    padding:0 !important;\r\n}\r\n#page.drawers .main-inner {\r\n    max-width: 100% !important;\r\n    width: 100% !important;\r\n}\r\n\r\n.container-fluid {\r\n    max-width: 100% !important;\r\n}\r\n\r\n.activity-item {\r\n    background: transparent !important;\r\n    border: none !important;\r\n    box-shadow: none !important;\r\n}\r\n\r\n.activity-item img {\r\n    width: 100% !important;\r\n    height: 600px !important;\r\n    object-fit: cover;\r\n    border-radius: 20px;\r\n}\r\n/* Remove unwanted spacing */\r\n\r\n#region-main {\r\n    padding-top: 0 !important;\r\n}\r\n\r\n.course-content {\r\n    padding-top: 0 !important;\r\n}\r\n\r\n.main-inner {\r\n    padding-top: 0 !important;\r\n}\r\n\r\n/* Hero image */\r\n\r\n.activity-item img {\r\n    width: 100%;\r\n    height: 650px;\r\n    object-fit: cover;\r\n    border-radius: 0;\r\n}\r\n\r\n/* Overlay text on image */\r\n\r\n.vk-hero-overlay {\r\n    position: absolute;\r\n    top: 180px;\r\n    left: 80px;\r\n    z-index: 100;\r\n    color: white;\r\n}\r\n\r\n.vk-hero-overlay h1 {\r\n    font-size: 56px;\r\n    font-weight: 700;\r\n    color: white !important;\r\n}\r\n\r\n.vk-hero-overlay p {\r\n    font-size: 22px;\r\n}\r\n.activity-item img {\r\n    width: 100%;\r\n    height: 650px;\r\n    object-fit: cover;\r\n    mask-image: linear-gradient(\r\n        to bottom,\r\n        transparent 0%,\r\n        rgba(0,0,0,.6) 15%,\r\n        black 40%,\r\n        black 100%\r\n    );\r\n}\r\n.hero-container {\r\n    position: relative;\r\n}\r\n\r\n.hero-container::before {\r\n    content: \"\";\r\n    position: absolute;\r\n    inset: 0;\r\n    background: rgba(0,0,0,.35);\r\n}\r\n/* Hero image */\r\n\r\n.activity-item img {\r\n    width: 100% !important;\r\n    height: 650px !important;\r\n    object-fit: cover;\r\n    border-radius: 20px;\r\n    opacity: 1 !important;\r\n    filter: brightness(100%);\r\n}\r\n\r\n.activity-item {\r\n    position: relative;\r\n}\r\n\r\n.activity-item::before{\r\n    content:\"\";\r\n    position:absolute;\r\n    top:0;\r\n    left:0;\r\n    width:100%;\r\n    height:100px;\r\n    background:linear-gradient(\r\n        rgba(255,255,255,0.25),\r\n        rgba(255,255,255,0)\r\n    );\r\n    pointer-events:none;\r\n    z-index:2;\r\n}\r\n', '/* ==========================================\r\n   VKOLLAB LMS CORPORATE THEME\r\n   ========================================== */\r\n\r\n/* Page Background */\r\nbody {\r\n    background: #f4f7fb !important;\r\n}\r\n\r\n/* Main Content Container */\r\n.main-inner {\r\n    background: #ffffff;\r\n    border-radius: 16px;\r\n    padding: 20px;\r\n    box-shadow: 0 4px 12px rgba(0,0,0,.08);\r\n}\r\n\r\n/* ==========================================\r\n   NAVIGATION BAR\r\n   ========================================== */\r\n\r\n.navbar {\r\n    background: #0F4C81 !important;\r\n    border-bottom: none !important;\r\n}\r\n\r\n.navbar-brand,\r\n.navbar .nav-link,\r\n.primary-navigation .navigation .nav-link,\r\n.moremenu .nav-link {\r\n    color: #ffffff !important;\r\n    font-weight: 600;\r\n}\r\n\r\n/* Active Menu */\r\n.navbar .nav-link.active,\r\n.moremenu .nav-link.active,\r\n.primary-navigation .navigation .nav-link.active {\r\n    color: #ffffff !important;\r\n    background: rgba(255,255,255,.15) !important;\r\n    border-radius: 6px;\r\n}\r\n\r\n/* Hover */\r\n.navbar .nav-link:hover,\r\n.moremenu .nav-link:hover,\r\n.primary-navigation .navigation .nav-link:hover {\r\n    color: #ffffff !important;\r\n    background: rgba(255,255,255,.10) !important;\r\n    border-radius: 6px;\r\n}\r\n\r\n/* Icons */\r\n.navbar i,\r\n.navbar .icon,\r\n.popover-region-toggle {\r\n    color: #ffffff !important;\r\n}\r\n\r\n/* User Menu */\r\n.usermenu *,\r\n.langmenu * {\r\n    color: #ffffff !important;\r\n}\r\n\r\n/* Edit Mode */\r\n.editmode-switch-form label {\r\n    color: #ffffff !important;\r\n}\r\n\r\n/* ==========================================\r\n   COURSE CARDS\r\n   =========