r\n.nav-tabs .nav-link.active {\r\n    background: #0F4C81 !important;\r\n    color: #ffffff !important;\r\n    border-radius: 6px;\r\n}\r\n \r\n.secondary-navigation .navigation .nav-link {\r\n    color: #0F4C81 !important;\r\n    font-weight: 600 !important;\r\n}\r\n \r\n.secondary-navigation .navigation .nav-link.active {\r\n    background: #0F4C81 !important;\r\n    color: white !important;\r\n}\r\n/* Full width LMS */\r\n\r\n#page.drawers .main-inner {\r\n    max-width: 100% !important;\r\n    width: 100% !important;\r\n}\r\n\r\n.container-fluid {\r\n    max-width: 100% !important;\r\n}\r\n\r\n.main-inner{\r\n    padding:0 !important;\r\n}\r\n#page.drawers .main-inner {\r\n    max-width: 100% !important;\r\n    width: 100% !important;\r\n}\r\n\r\n.container-fluid {\r\n    max-width: 100% !important;\r\n}\r\n\r\n.activity-item {\r\n    background: transparent !important;\r\n    border: none !important;\r\n    box-shadow: none !important;\r\n}\r\n\r\n.activity-item img {\r\n    width: 100% !important;\r\n    height: 600px !important;\r\n    object-fit: cover;\r\n    border-radius: 20px;\r\n}\r\n/* Remove unwanted spacing */\r\n\r\n#region-main {\r\n    padding-top: 0 !important;\r\n}\r\n\r\n.course-content {\r\n    padding-top: 0 !important;\r\n}\r\n\r\n.main-inner {\r\n    padding-top: 0 !important;\r\n}\r\n\r\n/* Hero image */\r\n\r\n.activity-item img {\r\n    width: 100%;\r\n    height: 650px;\r\n    object-fit: cover;\r\n    border-radius: 0;\r\n}\r\n\r\n/* Overlay text on image */\r\n\r\n.vk-hero-overlay {\r\n    position: absolute;\r\n    top: 180px;\r\n    left: 80px;\r\n    z-index: 100;\r\n    color: white;\r\n}\r\n\r\n.vk-hero-overlay h1 {\r\n    font-size: 56px;\r\n    font-weight: 700;\r\n    color: white !important;\r\n}\r\n\r\n.vk-hero-overlay p {\r\n    font-size: 22px;\r\n}\r\n.activity-item img {\r\n    width: 100%;\r\n    height: 650px;\r\n    object-fit: cover;\r\n    mask-image: linear-gradient(\r\n        to bottom,\r\n        transparent 0%