INSERT INTO `mdl_course` (`id`, `category`, `sortorder`, `fullname`, `shortname`, `idnumber`, `summary`, `summaryformat`, `format`, `showgrades`, `newsitems`, `startdate`, `enddate`, `relativedatesmode`, `marker`, `maxbytes`, `legacyfiles`, `showreports`, `visible`, `visibleold`, `downloadcontent`, `groupmode`, `groupmodeforce`, `defaultgroupingid`, `lang`, `calendartype`, `theme`, `timecreated`, `timemodified`, `requested`, `enablecompletion`, `completionnotify`, `cacherev`, `originalcourseid`, `showactivitydates`, `showcompletionconditions`, `pdfexportfont`) VALUES
(1, 0, 1, 'VKollab Learning Management System', 'VKLMS', '', '', 0, 'site', 1, 3, 0, 0, 0, 0, 0, 0, 0, 1, 1, NULL, 0, 0, 0, '', '', '', 1792589965, 1792590134, 0, 0, 0, 1793626470, NULL, 0, NULL, NULL),
(2, 4, 30001, 'Work Email Ettiquate', 'HR-COMP-001', 'ISC001', '<div>This course provides employees with an understanding of organizational policies, information security practices, workplace ethics, compliance requirements, and data protection responsibilities. Completion of this course is mandatory for all employees.</div>', 1, 'topics', 1, 5, 1792620000, 1824156000, 0, 0, 0, 0, 0, 1, 1, NULL, 0, 0, 0, '', '', '', 1792596791, 1793633795, 0, 1, 0, 1793633795, NULL, 1, 1, NULL),
(3, 2, 10002, 'Power Automate Fundamentals', 'TECH-PA-001', 'PA001', '<div>This course introduces Microsoft Power Automate and its capabilities in workflow automation. Learners will understand flows, triggers, actions, approvals, connectors, and automation best practices through practical examples.</div>', 1, 'topics', 1, 5, 1792620000, 1792879200, 0, 0, 0, 0, 0, 0, 0, NULL, 0, 0, 0, '', '', '', 1792605980, 1793280319, 0, 1, 0, 1793626470, NULL, 1, 1, NULL),
(4, 2, 10001, 'Artificial Intelligence', 'AI', '', '', 1, 'topics', 1, 5, 1792620000, 1824156000, 0, 0, 0, 0, 0, 0, 0, NULL, 0, 0, 0, '', '', '', 1792610189, 1793274212, 0, 1, 0, 1793626470, NULL, 1, 1, NULL),
(5, 2, 10003, 'SAP CPI', ' SAPCPI101', '', '<div>SAP Cloud Platform Integration (CPI) course covering integration flows, APIs, adapters, message mapping, and deployment.</div>', 1, 'topics', 1, 5, 1792792800, 1824328800, 0, 0, 0, 0, 0, 0, 0, NULL, 0, 0, 0, '', '', '', 1792764632, 1793281948, 0, 1, 0, 1793626470, NULL, 1, 1, NULL);
INSERT INTO `mdl_course_categories` (`id`, `name`, `idnumber`, `description`, `descriptionformat`, `parent`, `sortorder`, `coursecount`, `visible`, `visibleold`, `timemodified`, `depth`, `path`, `theme`) VALUES
(2, 'Technical Training', '', '<div>This category contains technical learning programs designed to enhance employees\' technical skills and knowledge. Courses include software development, automation, databases, cloud technologies, programming languages, and other technology-related topics that support professional growth and project delivery.</div>', 1, 0, 10000, 3, 1, 1, 1792596183, 1, '/2', NULL),
(3, 'Functional Training', '', '<div>This category focuses on role-based and function-specific training programs. Courses are designed to improve business, operational, and domain knowledge required to perform job responsibilities effectively and efficiently.</div>', 1, 0, 20000, 0, 1, 1, 1792596367, 1, '/3', NULL),
(4, 'HR & Compliance', '', '<div>\r\n<blockquote>\r\n<p>This category includes mandatory organizational training related to company policies, compliance requirements, workplace ethics, information security, data privacy, and employee conduct. These courses help ensure regulatory and organizational compliance.</p>\r\n</blockquote>\r\n</div>', 1, 0, 30000, 1, 1, 1, 1792596417, 1, '/4', NULL),
(5, 'Leadership Development', '', '<div>This category contains programs focused on developing leadership, management, communication, decision-making, and team collaboration skills. It is designed to support career growth and leadership readiness across the organization.</div>', 1, 0, 40000, 0, 1, 1, 1792596439, 1, '/5', NULL),
(6, 'Product & Process Training', '', '<div>This category provides training related to company products, services, internal systems, standard operating procedures, business processes, and onboarding programs. It helps employees understand organizational workflows and product knowledge.</div>', 1, 0, 50000, 0, 1, 1, 1792596625, 1, '/6', NULL);
