INSERT INTO `mdl_label` (`id`, `course`, `name`, `intro`, `introformat`, `timemodified`) VALUES
(1, 1, 'Text and media area', '<p><img class=\"img-fluid\" src=\"@@PLUGINFILE@@/image.png\"></p>', 1, 1792593522),
(2, 1, 'Text and media area', '<p><img class=\"img-fluid\" src=\"@@PLUGINFILE@@/image.png\"></p>', 1, 1792593628),
(3, 1, '<h2>Key Features</h2> <ul> <li>📚 Learning Paths</l...', '<div>&lt;h2&gt;Key Features&lt;/h2&gt;</div>\r\n<div> </div>\r\n<div>&lt;ul&gt;</div>\r\n<div>&lt;li&gt;📚 Learning Paths&lt;/li&gt;</div>\r\n<div>&lt;li&gt;📝 Assessments &amp; Quizzes&lt;/li&gt;</div>\r\n<div>&lt;li&gt;🎓 Certifications&lt;/li&gt;</div>\r\n<div>&lt;li&gt;📊 Reports &amp; Analytics&lt;/li&gt;</div>\r\n<div>&lt;li&gt;✅ Completion Tracking&lt;/li&gt;</div>\r\n<div>&lt;li&gt;📢 Announcements &amp; Feedback&lt;/li&gt;</div>\r\n<div>&lt;/ul&gt;</div>', 1, 1792593669),
(4, 1, 'Text and media area', '<p><img class=\"img-fluid\" src=\"@@PLUGINFILE@@/image.png\"></p>', 1, 1792593700),
(5, 2, 'Welcome to the Information Security & Compliance A...', '<div>Welcome to the Information Security &amp; Compliance Awareness Program.</div>\r\n<div> </div>\r\n<div>This course helps employees understand information security responsibilities, compliance requirements, workplace ethics, and organizational policies.</div>', 1, 1792597734),
(6, 2, 'Welcome Message', '<div>Welcome to the Information Security &amp; Compliance Awareness Program.</div>\r\n<div> </div>\r\n<div>This course is designed to help employees understand information security responsibilities, compliance requirements, workplace ethics, and organizational policies.</div>\r\n<div> </div>\r\n<div>By completing this course, learners will gain awareness of best practices for protecting company information and maintaining compliance standards.</div>', 1, 1792597933),
(7, 2, 'work email ettiquate', '<h6>  <video controls=\"controls\" width=\"1200\" height=\"675\">\r\n        <source src=\"@@PLUGINFILE@@/Workplace_Email_Etiquette.mp4\">\r\n    @@PLUGINFILE@@/Workplace_Email_Etiquette.mp4\r\n</video>  </h6>', 1, 1792695467),
(8, 1, 'Text and media area', '<p><img class=\"img-fluid\" src=\"@@PLUGINFILE@@/about-boardroom.jpg\" alt=\"VKollab Learning Management System\" width=\"1600\" height=\"900\"></p>', 1, 1792678883),
(9, 1, 'Learning management system', '<p><img src=\"@@PLUGINFILE@@/Designer%20%281%29.png\" alt=\"Professional corporate learning environment with employees collaborating around a laptop in a modern office, representing tra\" width=\"1413\" height=\"942\"></p>', 1, 1792683077),
(10, 1, 'Text and media area', '<p><img class=\"img-fluid\" src=\"@@PLUGINFILE@@/Designer.jpg\" alt=\"reterytretert\" width=\"1536\" height=\"1024\"></p>', 1, 1792696499),
(11, 2, 'work email ettiquate', '<p><a href=\"@@PLUGINFILE@@/Workplace_Email_Etiquette.mp4\">Workplace_Email_Etiquette.mp4</a></p>', 1, 1792697343),
(12, 2, 'Work Email Ettiquate', '<p> <video controls=\"controls\" width=\"1200\" height=\"675\">\r\n        <source src=\"@@PLUGINFILE@@/Workplace_Email_Etiquette.mp4\">\r\n    @@PLUGINFILE@@/Workplace_Email_Etiquette.mp4\r\n</video> </p>', 1, 1792700367);
