INSERT INTO `mdl_logstore_standard_log` (`id`, `eventname`, `component`, `action`, `target`, `objecttable`, `objectid`, `crud`, `edulevel`, `contextid`, `contextlevel`, `contextinstanceid`, `userid`, `courseid`, `relateduserid`, `anonymous`, `other`, `timecreated`, `origin`, `ip`, `realuserid`) VALUES
(767, '\\core\\event\\config_log_created', 'core', 'created', 'config_log', 'config_log', 1902, 'c', 0, 1, 10, 0, 2, 0, NULL, 0, '{\"name\":\"scss\",\"oldvalue\":\"\\/* ==========================================\\r\\n   VKOLLAB LMS CORPORATE THEME\\r\\n   ========================================== *\\/\\r\\n\\r\\n\\/* Page Background *\\/\\r\\nbody {\\r\\n    background: #f4f7fb !important;\\r\\n}\\r\\n\\r\\n\\/* Main Content Container *\\/\\r\\n.main-inner {\\r\\n    background: #ffffff;\\r\\n    border-radius: 16px;\\r\\n    padding: 20px;\\r\\n    box-shadow: 0 4px 12px rgba(0,0,0,.08);\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   NAVIGATION BAR\\r\\n   ========================================== *\\/\\r\\n\\r\\n.navbar {\\r\\n    background: #0F4C81 !important;\\r\\n    border-bottom: none !important;\\r\\n}\\r\\n\\r\\n.navbar-brand,\\r\\n.navbar .nav-link,\\r\\n.primary-navigation .navigation .nav-link,\\r\\n.moremenu .nav-link {\\r\\n    color: #ffffff !important;\\r\\n    font-weight: 600;\\r\\n}\\r\\n\\r\\n\\/* Active Menu *\\/\\r\\n.navbar .nav-link.active,\\r\\n.moremenu .nav-link.active,\\r\\n.primary-navigation .navigation .nav-link.active {\\r\\n    color: #ffffff !important;\\r\\n    background: rgba(255,255,255,.15) !important;\\r\\n    border-radius: 6px;\\r\\n}\\r\\n\\r\\n\\/* Hover *\\/\\r\\n.navbar .nav-link:hover,\\r\\n.moremenu .nav-link:hover,\\r\\n.primary-navigation .navigation .nav-link:hover {\\r\\n    color: #ffffff !important;\\r\\n    background: rgba(255,255,255,.10) !important;\\r\\n    border-radius: 6px;\\r\\n}\\r\\n\\r\\n\\/* Icons *\\/\\r\\n.navbar i,\\r\\n.navbar .icon,\\r\\n.popover-region-toggle {\\r\\n    color: #ffffff !important;\\r\\n}\\r\\n\\r\\n\\/* User Menu *\\/\\r\\n.usermenu *,\\r\\n.langmenu * {\\r\\n    color: #ffffff !important;\\r\\n}\\r\\n\\r\\n\\/* Edit Mode *\\/\\r\\n.editmode-switch-form label {\\r\\n    color: #ffffff !important;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   COURSE CARDS\\r\\n   ========================================== *\\/\\r\\n\\r\\n.coursebox,\\r\\n.card,\\r\\n.block {\\r\\n    border-radius: 12px;\\r\\n    border: none !important;\\r\\n    box-shadow: 0 4px 12px rgba(0,0,0,.08);\\r\\n    background: #ffffff;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   HEADINGS\\r\\n   ========================================== *\\/\\r\\n\\r\\nh1 {\\r\\n    color: #0F4C81 !important;\\r\\n    font-weight: 700;\\r\\n}\\r\\n\\r\\nh2 {\\r\\n    color: #1D70B8 !important;\\r\\n    font-weight: 600;\\r\\n}\\r\\n\\r\\nh3 {\\r\\n    color: #0F4C81 !important;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   LINKS\\r\\n   ========================================== *\\/\\r\\n\\r\\na {\\r\\n    color: #1D70B8;\\r\\n}\\r\\n\\r\\na:hover {\\r\\n    color: #0F4C81;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   BUTTONS\\r\\n   ========================================== *\\/\\r\\n\\r\\n.btn-primary {\\r\\n    background: #0F4C81 !important;\\r\\n    border-color: #0F4C81 !important;\\r\\n    border-radius: 8px;\\r\\n}\\r\\n\\r\\n.btn-primary:hover {\\r\\n    background: #1D70B8 !important;\\r\\n    border-color: #1D70B8 !important;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   DASHBOARD BLOCKS\\r\\n   ========================================== *\\/\\r\\n\\r\\n.block {\\r\\n    padding: 10px;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   SITE ADMINISTRATION PAGE FIX\\r\\n   ========================================== *\\/\\r\\n\\r\\n#page-admin-index .card,\\r\\n.path-admin .card {\\r\\n    background: #ffffff !important;\\r\\n    color: #0F4C81 !important;\\r\\n    border-radius: 12px;\\r\\n}\\r\\n\\r\\n\\/* Administration Category Titles *\\/\\r\\n#page-admin-index .category,\\r\\n#page-admin-index .card-title,\\r\\n.path-admin .card-title {\\r\\n    color: #0F4C81 !important;\\r\\n    font-weight: 600 !important;\\r\\n}\\r\\n\\r\\n\\/* Administration Links *\\/\\r\\n#page-admin-index a,\\r\\n.path-admin a {\\r\\n    color: #1D70B8 !important;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   ACTIVITY SECTIONS\\r\\n   ========================================== *\\/\\r\\n\\r\\n.activity-item {\\r\\n    margin-bottom: 15px;\\r\\n    padding: 15px;\\r\\n    border-radius: 10px;\\r\\n    background: #ffffff;\\r\\n    border: 1px solid #e5e7eb;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   TABLES\\r\\n   ========================================== *\\/\\r\\n\\r\\n.generaltable {\\r\\n    border-radius: 8px;\\r\\n    overflow: hidden;\\r\\n}\\r\\n\\r\\n.generaltable th {\\r\\n    background: #0F4C81 !important;\\r\\n    color: white !important;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   FOOTER\\r\\n   ========================================== *\\/\\r\\n\\r\\n#page-footer {\\r\\n    background: #0F4C81;\\r\\n    color: #ffffff;\\r\\n    padding: 15px;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   CUSTOM HOMEPAGE BANNER\\r\\n   ========================================== *\\/\\r\\n\\r\\n.vk-banner {\\r\\n    background: linear-gradient(135deg,#0F4C81,#1D70B8);\\r\\n    color: white;\\r\\n    padding: 50px;\\r\\n    border-radius: 16px;\\r\\n    text-align: center;\\r\\n    margin-bottom: 20px;\\r\\n}\\r\\n\\r\\n.vk-banner h1 {\\r\\n    color: #ffffff !important;\\r\\n}\\r\\n\\r\\n.vk-banner p {\\r\\n    color: #ffffff !important;\\r\\n    font-size: 18px;\\r\\n}\\r\\n\\/* Existing VKollab Theme CSS *\\/\\r\\n\\/* ...all your current code... *\\/\\r\\n \\r\\n\\/* ===================================\\r\\n   Admin Menu Visibility Fix\\r\\n   =================================== *\\/\\r\\n \\r\\n.nav-tabs .nav-link,\\r\\n.nav-link {\\r\\n    color: #0F4C81 !important;\\r\\n    font-weight: 600 !important;\\r\\n}\\r\\n \\r\\n.nav-tabs .nav-link:hover {\\r\\n    color: #081B4B !important;\\r\\n    background: #eef4fb !important;\\r\\n}\\r\\n \\r\\n.nav-tabs .nav-link.active {\\r\\n    background: #0F4C81 !important;\\r\\n    color: #ffffff !important;\\r\\n    border-radius: 6px;\\r\\n}\\r\\n \\r\\n.secondary-navigation .navigation .nav-link {\\r\\n    color: #0F4C81 !important;\\r\\n    font-weight: 600 !important;\\r\\n}\\r\\n \\r\\n.secondary-navigation .navigation .nav-link.active {\\r\\n    background: #0F4C81 !important;\\r\\n    color: white !important;\\r\\n}\\r\\n\\/* Full width LMS *\\/\\r\\n\\r\\n#page.drawers .main-inner {\\r\\n    max-width: 100% !important;\\r\\n    width: 100% !important;\\r\\n}\\r\\n\\r\\n.container-fluid {\\r\\n    max-width: 100% !important;\\r\\n}\\r\\n\\r\\n.main-inner{\\r\\n    padding:0 !important;\\r\\n}\\r\\n#page.drawers .main-inner {\\r\\n    max-width: 100% !important;\\r\\n    width: 100% !important;\\r\\n}\\r\\n\\r\\n.container-fluid {\\r\\n    max-width: 100% !important;\\r\\n}\\r\\n\\r\\n.activity-item {\\r\\n    background: transparent !important;\\r\\n    border: none !important;\\r\\n    box-shadow: none !important;\\r\\n}\\r\\n\\r\\n.activity-item img {\\r\\n    width: 100% !important;\\r\\n    height: 600px !important;\\r\\n    object-fit: cover;\\r\\n    border-radius: 20px;\\r\\n}\\r\\n\\/* Remove unwanted spacing *\\/\\r\\n\\r\\n#region-main {\\r\\n    padding-top: 0 !important;\\r\\n}\\r\\n\\r\\n.course-content {\\r\\n    padding-top: 0 !important;\\r\\n}\\r\\n\\r\\n.main-inner {\\r\\n    padding-top: 0 !important;\\r\\n}\\r\\n\\r\\n\\/* Hero image *\\/\\r\\n\\r\\n.activity-item img {\\r\\n    width: 100%;\\r\\n    height: 650px;\\r\\n    object-fit: cover;\\r\\n    border-radius: 0;\\r\\n}\\r\\n\\r\\n\\/* Overlay text on image *\\/\\r\\n\\r\\n.vk-hero-overlay {\\r\\n    position: absolute;\\r\\n    top: 180px;\\r\\n    left: 80px;\\r\\n    z-index: 100;\\r\\n    color: white;\\r\\n}\\r\\n\\r\\n.vk-hero-overlay h1 {\\r\\n    font-size: 56px;\\r\\n    font-weight: 700;\\r\\n    color: white !important;\\r\\n}\\r\\n\\r\\n.vk-hero-overlay p {\\r\\n    font-size: 22px;\\r\\n}\\r\\n.activity-item img {\\r\\n    width: 100%;\\r\\n    height: 650px;\\r\\n    object-fit: cover;\\r\\n    mask-image: linear-gradient(\\r\\n        to bottom,\\r\\n        transparent 0%,\\r\\n        rgba(0,0,0,.6) 15%,\\r\\n        black 40%,\\r\\n        black 100%\\r\\n    );\\r\\n}\\r\\n.hero-container {\\r\\n    position: relative;\\r\\n}\\r\\n\\r\\n.hero-container::before {\\r\\n    content: \\\"\\\";\\r\\n    position: absolute;\\r\\n    inset: 0;\\r\\n    background: rgba(0,0,0,.35);\\r\\n}\\r\\n\\/* Hero image *\\/\\r\\n\\r\\n.activity-item img {\\r\\n    width: 100% !important;\\r\\n    height: 650px !important;\\r\\n    object-fit: cover;\\r\\n    border-radius: 20px;\\r\\n    opacity: 1 !important;\\r\\n    filter: brightness(100%);\\r\\n}\\r\\n\\r\\n.activity-item {\\r\\n    position: relative;\\r\\n}\\r\\n\\r\\n.activity-item::before{\\r\\n    content:\\\"\\\";\\r\\n    position:absolute;\\r\\n    top:0;\\r\\n    left:0;\\r\\n    width:100%;\\r\\n    height:100px;\\r\\n    background:linear-gradient(\\r\\n        rgba(255,255,255,0.25),\\r\\n        rgba(255,255,255,0)\\r\\n    );\\r\\n    pointer-events:none;\\r\\n    z-index:2;\\r\\n}\\r\\n\",\"value\":\"\\/* ==========================================\\r\\n   VKOLLAB LMS CORPORATE THEME\\r\\n   ========================================== *\\/\\r\\n\\r\\n\\/* Page Background *\\/\\r\\nbody {\\r\\n    background: #f4f7fb !important;\\r\\n}\\r\\n\\r\\n\\/* Main Content Container *\\/\\r\\n.main-inner {\\r\\n    background: #ffffff;\\r\\n    border-radius: 16px;\\r\\n    padding: 20px;\\r\\n    box-shadow: 0 4px 12px rgba(0,0,0,.08);\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   NAVIGATION BAR\\r\\n   ========================================== *\\/\\r\\n\\r\\n.navbar {\\r\\n    background: #0F4C81 !important;\\r\\n    border-bottom: none !important;\\r\\n}\\r\\n\