\n.popover-region-toggle {\\r\\n    color: #ffffff !important;\\r\\n}\\r\\n\\r\\n\\/* User Menu *\\/\\r\\n.usermenu *,\\r\\n.langmenu * {\\r\\n    color: #ffffff !important;\\r\\n}\\r\\n\\r\\n\\/* Edit Mode *\\/\\r\\n.editmode-switch-form label {\\r\\n    color: #ffffff !important;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   COURSE CARDS\\r\\n   ========================================== *\\/\\r\\n\\r\\n.coursebox,\\r\\n.card,\\r\\n.block {\\r\\n    border-radius: 12px;\\r\\n    border: none !important;\\r\\n    box-shadow: 0 4px 12px rgba(0,0,0,.08);\\r\\n    background: #ffffff;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   HEADINGS\\r\\n   ========================================== *\\/\\r\\n\\r\\nh1 {\\r\\n    color: #0F4C81 !important;\\r\\n    font-weight: 700;\\r\\n}\\r\\n\\r\\nh2 {\\r\\n    color: #1D70B8 !important;\\r\\n    font-weight: 600;\\r\\n}\\r\\n\\r\\nh3 {\\r\\n    color: #0F4C81 !important;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   LINKS\\r\\n   ========================================== *\\/\\r\\n\\r\\na {\\r\\n    color: #1D70B8;\\r\\n}\\r\\n\\r\\na:hover {\\r\\n    color: #0F4C81;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   BUTTONS\\r\\n   ========================================== *\\/\\r\\n\\r\\n.btn-primary {\\r\\n    background: #0F4C81 !important;\\r\\n    border-color: #0F4C81 !important;\\r\\n    border-radius: 8px;\\r\\n}\\r\\n\\r\\n.btn-primary:hover {\\r\\n    background: #1D70B8 !important;\\r\\n    border-color: #1D70B8 !important;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   DASHBOARD BLOCKS\\r\\n   ========================================== *\\/\\r\\n\\r\\n.block {\\r\\n    padding: 10px;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   SITE ADMINISTRATION PAGE FIX\\r\\n   ========================================== *\\/\\r\\n\\r\\n#page-admin-index .card,\\r\\n.path-admin .card {\\r\\n    background: #ffffff !important;\\r\\n    color: #0F4C81 !important;\\r\\n    border-radius: 12px;\\r\\n}\\r\\n\\r\\n\\/* Administration Category Titles *\\/\\r\\n#page-admin-index .category,\\r\\n#page-admin-index .card-title,\\r\\n.path-admin .card-title {\\r\\n    color: #0F4C81 !important;\\r\\n    font-weight: 600 !important;\\r\\n}\\r\\n\\r\\n\\/* Administration Links *\\/\\r\\n#page-admin-index a,\\r\\n.path-admin a {\\r\\n    color: #1D70B8 !important;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   ACTIVITY SECTIONS\\r\\n   ========================================== *\\/\\r\\n\\r\\n.activity-item {\\r\\n    margin-bottom: 15px;\\r\\n    padding: 15px;\\r\\n    border-radius: 10px;\\r\\n    background: #ffffff;\\r\\n    border: 1px solid #e5e7eb;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   TABLES\\r\\n   ========================================== *\\/\\r\\n\\r\\n.generaltable {\\r\\n    border-radius: 8px;\\r\\n    overflow: hidden;\\r\\n}\\r\\n\\r\\n.generaltable th {\\r\\n    background: #0F4C81 !important;\\r\\n    color: white !important;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   FOOTER\\r\\n   ========================================== *\\/\\r\\n\\r\\n#page-footer {\\r\\n    background: #0F4C81;\\r\\n    color: #ffffff;\\r\\n    padding: 15px;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   CUSTOM HOMEPAGE BANNER\\r\\n   ========================================== *\\/\\r\\n\\r\\n.vk-banner {\\r\\n    background: linear-gradient(135deg,#0F4C81,#1D70B8);\\r\\n    color: white;\\r\\n    padding: 50px;\\r\\n    border-radius: 16px;\\r\\n    text-align: center;\\r\\n    margin-bottom: 20px;\\r\\n}\\r\\n\\r\\n.vk-banner h1 {\\r\\n    color: #ffffff !important;\\r\\n}\\r\\n\\r\\n.vk-banner p {\\r\\n    color: #ffffff !important;\\r\\n    font-size: 18px;\\r\\n}\\r\\n\\/* Existing VKollab Theme CSS *\\/\\r\\n\\/* ...all your current code... *\\/\\r\\n \\r\\n\\/* ===================================\\r\\n   Admin Menu Visibility Fix\\r\\n   =================================== *\\/\\r\\n \\r\\n.nav-tabs .nav-link,\\r\\n.nav-link {\\r\\n    color: #0F4C81 !important;\\r\\n    font-weight: 600 !important;\\r\\n}\\r\\n \\r\\n.nav-tabs .nav-link:hover {\\r\\n    color: #081B4B !important;\\r\\n    background: #eef4fb !important;\\r\\n}\\r\\n \\r\\n.nav-tabs .nav-link.active {\\r\\n    background: #0F4C81 !important;\\r\\n    color: #ffffff !important;\\r\\n    border-radius: 6px;\\r\\n}\\r\\n \\r\\n.secondary-navigation .navigation .nav-link {\\r\\n    color: #0F4C81 !important;\\r\\n    font-weight: 600 !important;\\r\\n}\\r\\n \\r\\n.secondary-navigation .navigation .nav-link.active {\\r\\n    background: #0F4C81 !important;\\r\\n    color: white !important;\\r\\n}\\r\\n\\/* Full width LMS *\\/\\r\\n\\r\\n#page.drawers .main-inner {\\r\\n    max-width: 100% !important;\\r\\n    width: 100% !important;\\r\\n}\\r\\n\\r\\n.container-fluid {\\r\\n    max-width: 100% !important;\\r\\n}\\r\\n\\r\\n.main-inner{\\r\\n    padding:0 !important;\\r\\n}\\r\\n#page.drawers .main-inner {\\r\\n    max-width: 100% !important;\\r\\n    width: 100% !important;\\r\\n}\\r\\n\\r\\n.container-fluid {\\r\\n    max-width: 100% !important;\\r\\n}\\r\\n\\r\\n.activity-item {\\r\\n    background: transparent !important;\\r\\n    border: none !important;\\r\\n    box-shadow: none !important;\\r\\n}\\r\\n\\r\\n.activity-item img {\\r\\n    width: 100% !important;\\r\\n    height: 600px !important;\\r\\n    object-fit: cover;\\r\\n    border-radius: 20px;\\r\\n}\\r\\n\\/* Remove unwanted spacing *\\/\\r\\n\\r\\n#region-main {\\r\\n    padding-top: 0 !important;\\r\\n}\\r\\n\\r\\n.course-content {\\r\\n    padding-top: 0 !important;\\r\\n}\\r\\n\\r\\n.main-inner {\\r\\n    padding-top: 0 !important;\\r\\n}\\r\\n\\r\\n\\/* Hero image *\\/\\r\\n\\r\\n.activity-item img {\\r\\n    width: 100%;\\r\\n    height: 650px;\\r\\n    object-fit: cover;\\r\\n    border-radius: 0;\\r\\n}\\r\\n\\r\\n\\/* Overlay text on image *\\/\\r\\n\\r\\n.vk-hero-overlay {\\r\\n    position: absolute;\\r\\n    top: 180px;\\r\\n    left: 80px;\\r\\n    z-index: 100;\\r\\n    color: white;\\r\\n}\\r\\n\\r\\n.vk-hero-overlay h1 {\\r\\n    font-size: 56px;\\r\\n    font-weight: 700;\\r\\n    color: white !important;\\r\\n}\\r\\n\\r\\n.vk-hero-overlay p {\\r\\n    font-size: 22px;\\r\\n}\\r\\n.activity-item img {\\r\\n    width: 100%;\\r\\n    height: 650px;\\r\\n    object-fit: cover;\\r\\n    mask-image: linear-gradient(\\r\\n        to bottom,\\r\\n        transparent 0%,\\r\\n        rgba(0,0,0,.6) 15%,\\r\\n        black 40%,\\r\\n        black 100%\\r\\n    );\\r\\n}\\r\\n.hero-container {\\r\\n    position: relative;\\r\\n}\\r\\n\\r\\n.hero-container::before {\\r\\n    content: \\\"\\\";\\r\\n    position: absolute;\\r\\n    inset: 0;\\r\\n    background: rgba(0,0,0,.35);\\r\\n}\\r\\n\\/* Hero image *\\/\\r\\n\\r\\n.activity-item img {\\r\\n    width: 100% !important;\\r\\n    height: 650px !important;\\r\\n    object-fit: cover;\\r\\n    border-radius: 20px;\\r\\n    opacity: 1 !important;\\r\\n    filter: brightness(100%);\\r\\n}\\r\\n\\r\\n.activity-item {\\r\\n    position: relative;\\r\\n}\\r\\n\\r\\n.activity-item::before{\\r\\n    content:\\\"\\\";\\r\\n    position:absolute;\\r\\n    top:0;\\r\\n    left:0;\\r\\n    width:100%;\\r\\n    height:100px;\\r\\n    background:linear-gradient(\\r\\n        rgba(255,255,255,0.25),\\r\\n        rgba(255,255,255,0)\\r\\n    );\\r\\n    pointer-events:none;\\r\\n    z-index:2;\\r\\n}\\r\\n\\/* ==========================\\r\\n   VKollab Login Page\\r\\n   ========================== *\\/\\r\\n\\r\\n.path-login {\\r\\n    background: url(\'http:\\/\\/localhost\\/images\\/loginpage.png\') center center no-repeat fixed !important;\\r\\n    background-size: cover !important;\\r\\n    min-height: 100vh;\\r\\n}\\r\\n\\r\\n\\/* Soft overlay for readability *\\/\\r\\n.path-login::before {\\r\\n    content: \\\"\\\";\\r\\n    position: fixed;\\r\\n    inset: 0;\\r\\n    background: rgba(255,255,255,0.15);\\r\\n    z-index: 0;\\r\\n}\\r\\n\\r\\n\\/* Login card *\\/\\r\\n.path-login .card {\\r\\n    background: rgba(255,255,255,0.95);\\r\\n    border: none;\\r\\n    border-radius: 20px;\\r\\n    box-shadow: 0 12px 35px rgba(0,0,0,.15);\\r\\n}\\r\\n\\r\\n\\/* Keep login card above background *\\/\\r\\n.path-login #page {\\r\\n    position: relative;\\r\\n    z-index: 2;\\r\\n}\\r\\n\\r\\n\\/* Login button *\\/\\r\\n.path-login .btn-primary {\\r\\n    background: #0F4C81 !important;\\r\\n    border-color: #0F4C81 !important;\\r\\n    border-radius: 10px;\\r\\n}\\r\\n\\/* Force login background *\\/\\r\\n\\r\\nbody.path-login {\\r\\n    background-image: url(\'http:\\/\\/localhost\\/images\\/loginpage.png\') !important;\\r\\n    background-size: cover !important;\\r\\n    background-position: center center !important;\\r\\n    background-repeat: no-repeat !important;\\r\\n    background-attachment: fixed !important;\\r\\n}\\r\\n\\r\\nbody.path-login #page-wrapper {\\r\\n    background: transparent !important;\\r\\n}\\r\\n\\r\\nbody.path-login #page {\\r\\n    background: transparent !important;\\r\\n}\\r\\n\\r\\nbody.path-login {\\r\\n    min-height: 100vh;\\r\\n}\\r\\n\\/* =========================\\r\\n   Profile Dropdown Menu\\r\\n   ========================= *\\/\\r\\n \\r\\n.dropdown-menu {\\r\\n    background-color: #ffffff !important;\\r\\n    border-radius: 10px;\\r\\n    border: 1px solid #dce3ea;\\r\\n    box-shadow: 0 4px 12px rgba(0,0,0,.15);\\r\\n}\\r\\n \\r\\n.dropdown-menu .dropdown-item {\\r\\n    color: #212529 !important;\\r\\n    font-weight: 500;\\r\\n}\\r\\n \\r\\n.dropdown-menu .dropdown-item:hover,\\r\\n.dropdown-menu .dropdown-item:focus {\\r\\n    background-color: #f5f7fa !important;\\r\\n    color: #0056b3 !important;\\r\\n}\\r\\n \\r\\n\\/* =========================\\r\\n   Notification & Message Panels\