 color: #212529 !important;\\r\\n}\\r\\n \\r\\n\\/* =========================\\r\\n   Responsive Images\\r\\n   ========================= *\\/\\r\\n \\r\\nimg {\\r\\n    max-width: 100%;\\r\\n    height: auto;\\r\\n}\\r\\n.block_calendar_month .calendarwrapper {\\r\\n    background: #ffffff;\\r\\n    border-radius: 12px;\\r\\n    padding: 15px;\\r\\n    box-shadow: 0 4px 12px rgba(0,0,0,.08);\\r\\n    border: 1px solid #D9E2EC;\\r\\n}\\r\\n\\r\\n.block_calendar_month h3,\\r\\n.block_calendar_month .current {\\r\\n    color: #005A9C;\\r\\n    font-weight: 600;\\r\\n}\\r\\n\\r\\n.block_calendar_month table {\\r\\n    border-radius: 10px;\\r\\n    overflow: hidden;\\r\\n}\\r\\n\\r\\n.block_calendar_month td,\\r\\n.block_calendar_month th {\\r\\n    border: 1px solid #E5E7EB;\\r\\n}\\r\\n\\r\\n.block_calendar_month .today {\\r\\n    background: #0078D4 !important;\\r\\n    color: white !important;\\r\\n    border-radius: 50%;\\r\\n}\\r\\n\\/* Calendar Container *\\/\\r\\n.block_calendar_month,\\r\\n.maincalendar {\\r\\n    background: #ffffff;\\r\\n    border-radius: 16px;\\r\\n    padding: 15px;\\r\\n    border: 1px solid #D9E2EC;\\r\\n    box-shadow: 0 4px 12px rgba(0,0,0,.08);\\r\\n}\\r\\n\\r\\n\\/* Month Title *\\/\\r\\n.calendar-controls h2,\\r\\n.maincalendar h2 {\\r\\n    color: #003B6F;\\r\\n    font-weight: 700;\\r\\n}\\r\\n\\r\\n\\/* Day Headers *\\/\\r\\n.maincalendar th {\\r\\n    background: #F8FAFC;\\r\\n    color: #44546A;\\r\\n    font-weight: 600;\\r\\n}\\r\\n\\r\\n\\/* Calendar Cells *\\/\\r\\n.maincalendar td {\\r\\n    border: 1px solid #E5E7EB;\\r\\n    background: #FFFFFF;\\r\\n}\\r\\n\\r\\n\\/* Today *\\/\\r\\n.maincalendar .today {\\r\\n    background: #0078D4 !important;\\r\\n    color: white !important;\\r\\n    border-radius: 50%;\\r\\n}\\r\\n\\r\\n\\/* Event Button *\\/\\r\\n.maincalendar .btn-primary {\\r\\n    background: #005A9C;\\r\\n    border-color: #005A9C;\\r\\n}\\r\\n\\r\\n\\/* Hover *\\/\\r\\n.maincalendar td:hover {\\r\\n    background: #F5F9FF;\\r\\n}\\r\\na[href*=\\\"grade\\\"],\\r\\na[href*=\\\"files.php\\\"] {\\r\\n    display: none !important;\\r\\n}\\r\\n .usermenu a[href*=\\\"reportbuilder\\\"] {\\r\\n    display: none !important;\\r\\n}\\r\\na[href*=\\\"editorsettings\\\"] {\\r\\n    display: none !important;\\r\\n}\\r\\n\\r\\na[href*=\\\"contentbank\\\"] {\\r\\n    display: none !important;\\r\\n}\\r\\n#page-user-preferences .card:nth-child(2),\\r\\n#page-user-preferences a[href*=\\\"badges\\\"],\\r\\n#page-user-preferences a[href*=\\\"badge\\\"] {\\r\\n    display: none !important;\\r\\n}\\r\\n\\/* Hide Editor preferences *\\/\\r\\na[href*=\\\"preferences.php?userid\\\"][href*=\\\"editor\\\"] {\\r\\n    display: none !important;\\r\\n}\\r\\n \\r\\n\\/* Hide Message preferences *\\/\\r\\na[href*=\\\"message\\\"] {\\r\\n    display: none !important;\\r\\n}\\r\\n \\r\\n\\/* Hide Badges card completely *\\/\\r\\n#page-user-preferences .card:nth-of-type(2) {\\r\\n    display: none !important;\\r\\n}\\r\\n\\/* Hide Badges card *\\/\\r\\n#page-user-preferences .row .col-md-4:last-child {\\r\\n    display: none !important;\\r\\n}\\r\\na[href*=\\\"\\/user\\/editor.php\\\"] {\\r\\n    display: none !important;\\r\\n}\\r\\n\\/* Hide MoodleNet Profile ID *\\/\\r\\n#id_moodlenetprofile,\\r\\nlabel[for=\\\"id_moodlenetprofile\\\"] {\\r\\n    display:none !important;\\r\\n}\\r\\n\\/* Hide MoodleNet Profile ID completely *\\/\\r\\n#fitem_id_moodlenetprofile {\\r\\n    display: none !important;\\r\\n}\\r\\n\\/* Hide Privacy and Policies *\\/\\r\\n#page-user-profile a[href*=\\\"tool_dataprivacy\\\"],\\r\\n#page-user-profile .node_category.privacyandpolicies {\\r\\n    display: none !important;\\r\\n}\\r\\n\\/* Hide Forum Posts and Forum Discussions *\\/\\r\\n#page-user-profile a[href*=\\\"forum\\/user.php\\\"],\\r\\n#page-user-profile a[href*=\\\"forum\\/discussions.php\\\"] {\\r\\n    display: none !important;\\r\\n}\\r\\n\\/* Hide Course Details card *\\/\\r\\n#page-user-profile .profile_tree section:has(a[href*=\\\"course\\/view.php\\\"]) {\\r\\n    display: none !important;\\r\\n}\\r\\n#page-user-profile .contentnode:last-of-type {\\r\\n    display: none !important;\\r\\n}\\r\\n\\/* Hide Course Details link *\\/\\r\\n#page-user-profile a[href*=\\\"\\/course\\/view.php\\\"] {\\r\\n    display: none !important;\\r\\n}\\r\\n\\/* Hide Course Details card *\\/\\r\\n#page-user-profile .contentnode:has(a[href*=\\\"\\/course\\/view.php\\\"]) {\\r\\n    display: none !important;\\r\\n}\\r\\n\\/* Remove entire Course Details card *\\/\\r\\n#page-user-profile .profile_tree section:nth-child(2) {\\r\\n    display: none !important;\\r\\n}\\r\\n\\r\\n\\/* Remove Privacy and Policies card *\\/\\r\\n#page-user-profile .profile_tree section:has(a[href*=\\\"tool_dataprivacy\\\"]),\\r\\n#page-user-profile .contentnode:has(a[href*=\\\"tool_dataprivacy\\\"]) {\\r\\n    display: none !important;\\r\\n}\\r\\n\\/* Hide empty Course Details card *\\/\\r\\n#page-user-profile .contentnode:empty {\\r\\n    display: none !important;\\r\\n}\\r\\n\\r\\n\\/* Hide card if course profile links are removed *\\/\\r\\n#page-user-profile .profile_tree .contentnode {\\r\\n    min-height: auto !important;\\r\\n}\\r\\n\\/* Hide the bottom-left Course Details card *\\/\\r\\n#page-user-profile .profile_tree .row .col-md-6:last-child {\\r\\n    display: none !important;\\r\\n}\\r\\n\\/* Hide empty profile cards *\\/\\r\\n#page-user-profile .contentnode {\\r\\n    display: none !important;\\r\\n}\\r\\n\\r\\n\\/* Keep required sections visible *\\/\\r\\n#page-user-profile .contentnode.userdetails,\\r\\n#page-user-profile .contentnode.miscellaneous,\\r\\n#page-user-profile .contentnode.reports,\\r\\n#page-user-profile .contentnode.loginactivity {\\r\\n    display: block !important;\\r\\n}\",\"plugin\":\"theme_boost\"}', 1793628859, 'web', '0:0:0:0:0:0:0:1', NULL),
