forum\\/discussions.php\\\"] {\\r\\n    display: none !important;\\r\\n}\\r\\n\\/* Hide Course Details card *\\/\\r\\n#page-user-profile .profile_tree section:has(a[href*=\\\"course\\/view.php\\\"]) {\\r\\n    display: none !important;\\r\\n}\\r\\n\\/* Hide Course Details link *\\/\\r\\n#page-user-profile a[href*=\\\"\\/course\\/view.php\\\"] {\\r\\n    display: none !important;\\r\\n}\\r\\n\\/* Hide Course Details card *\\/\\r\\n#page-user-profile .contentnode:has(a[href*=\\\"\\/course\\/view.php\\\"]) {\\r\\n    display: none !important;\\r\\n}\\r\\n\\/* Remove entire Course Details card *\\/\\r\\n\\r\\n\\/* Remove Privacy and Policies card *\\/\\r\\n#page-user-profile .profile_tree section:has(a[href*=\\\"tool_dataprivacy\\\"]),\\r\\n#page-user-profile .contentnode:has(a[href*=\\\"tool_dataprivacy\\\"]) {\\r\\n    display: none !important;\\r\\n}\\r\\n\\/* Hide empty Course Details card *\\/\\r\\n\\r\\n\\/* Hide card if course profile links are removed *\\/\\r\\n#page-user-profile .profile_tree .contentnode {\\r\\n    min-height: auto !important;\\r\\n}\\r\\n\\/* Hide the bottom-left Course Details card *\\/\\r\\n\\/* Hide empty profile cards *\\/\\r\\n#page-user-profile .contentnode {\\r\\n    display: none !important;\\r\\n}\\r\\n\\r\\n\\/* Keep required sections visible *\\/\\r\\n#page-user-profile .contentnode.userdetails,\\r\\n#page-user-profile .contentnode.miscellaneous,\\r\\n#page-user-profile .contentnode.reports,\\r\\n#page-user-profile .contentnode.loginactivity {\\r\\n    display: block !important;\\r\\n}\\r\\n\\/* Hide Course Details block *\\/\\r\\n#page-user-profile .node_category.course {\\r\\n    display: none !important;\\r\\n}\\r\\n\\/* Hide Privacy and Policies card *\\/\\r\\n#page-user-profile .contentnode:has(a[href*=\\\"tool_dataprivacy\\\"]),\\r\\n#page-user-profile .profile_tree section:has(a[href*=\\\"tool_dataprivacy\\\"]) {\\r\\n    display: none !important;\\r\\n}\\r\\n\\/* Hide Course Details section *\\/\\r\\n#page-user-profile .contentnode:has(h3),\\r\\n#page-user-profile .contentnode:has(.courseprofiles) {\\r\\n    display: none !important;\\r\\n}\\r\\n\",\"plugin\":\"theme_boost\"}', 1793629680, 'web', '0:0:0:0:0:0:0:1', NULL),
