(5581, '\\core\\event\\email_failed', 'core', 'failed', 'email', NULL, NULL, 'c', 0, 1, 10, 0, -20, 0, 9, 0, '{\"subject\":\"VKollab Learning Management System: Password reset request\",\"message\":\"Hi Mahesh,\\n\\nA password reset was requested for your account \'mahesh\' at VKollab\\nLearning Management System.\\n\\nTo confirm this request, and set a new password for your account, please\\nclick the link below:\\n\\nReset password [1]\\n\\n(This link is valid for 30 minutes from the time this reset was first\\nrequested.)\\n\\nIf this password reset was not requested by you, no action is needed.\\n\\nIf you need help, please contact the site administrator.\\n\\nAdmin User\\n\\n\\nLinks:\\n------\\n[1] http:\\/\\/localhost\\/moodle\\/login\\/forgot_password.php?token=HOgZJFPiGt98wCMEDoyHAH0CT1NHwzQt\",\"errorinfo\":\"Could not instantiate mail function.\"}', 1793634780, 'web', '0:0:0:0:0:0:0:1', NULL);
INSERT INTO `mdl_logstore_standard_log` (`id`, `eventname`, `component`, `action`, `target`, `objecttable`, `objectid`, `crud`, `edulevel`, `contextid`, `contextlevel`, `contextinstanceid`, `userid`, `courseid`, `relateduserid`, `anonymous`, `other`, `timecreated`, `origin`, `ip`, `realuserid`) VALUES
(5582, '\\core\\event\\config_log_created', 'core', 'created', 'config_log', 'config_log', 2006, 'c', 0, 1, 10, 0, 2, 0, NULL, 0, '{\"name\":\"scss\",\"oldvalue\":\"\\/* ==========================================\\r\\n   VKOLLAB LMS CORPORATE THEME\\r\\n   ========================================== *\\/\\r\\n\\r\\n\\/* Page Background *\\/\\r\\nbody {\\r\\n    background: #f4f7fb !important;\\r\\n}\\r\\n\\/* Hide Course Details card *\\/\\r\\n\\/*\\r\\n#page-user-profile .contentnode.coursecontact,\\r\\n#page-user-profile .profile_tree section:last-child {\\r\\n    display: none !important;\\r\\n}\\r\\n*\\/\\r\\n[data-fieldtype=\\\"institution\\\"],\\r\\n#id_institution,\\r\\n.fitem:has(#id_institution) {\\r\\n    display: none !important;\\r\\n}\\r\\n\\r\\n\\/* Main Content Container *\\/\\r\\n.main-inner {\\r\\n    background: #ffffff;\\r\\n    border-radius: 16px;\\r\\n    padding: 20px;\\r\\n    box-shadow: 0 4px 12px rgba(0,0,0,.08);\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   NAVIGATION BAR\\r\\n   ========================================== *\\/\\r\\n\\r\\n.navbar {\\r\\n    background: #0F4C81 !important;\\r\\n    border-bottom: none !important;\\r\\n}\\r\\n\\r\\n.navbar-brand,\\r\\n.navbar .nav-link,\\r\\n.primary-navigation .navigation .nav-link,\\r\\n.moremenu .nav-link {\\r\\n    color: #ffffff !important;\\r\\n    font-weight: 600;\\r\\n}\\r\\n\\r\\n\\/* Active Menu *\\/\\r\\n.navbar .nav-link.active,\\r\\n.moremenu .nav-link.active,\\r\\n.primary-navigation .navigation .nav-link.active {\\r\\n    color: #ffffff !important;\\r\\n    background: rgba(255,255,255,.15) !important;\\r\\n    border-radius: 6px;\\r\\n}\\r\\n\\r\\n\\/* Hover *\\/\\r\\n.navbar .nav-link:hover,\\r\\n.moremenu .nav-link:hover,\\r\\n.primary-navigation .navigation .nav-link:hover {\\r\\n    color: #ffffff !important;\\r\\n    background: rgba(255,255,255,.10) !important;\\r\\n    border-radius: 6px;\\r\\n}\\r\\n\\r\\n\\/* Icons *\\/\\r\\n.navbar i,\\r\\n.navbar .icon,\\r\\n.popover-region-toggle {\\r\\n    color: #ffffff !important;\\r\\n}\\r\\n\\r\\n\\/* User Menu *\\/\\r\\n.usermenu *,\\r\\n.langmenu * {\\r\\n    color: #ffffff !important;\\r\\n}\\r\\n\\r\\n\\/* Edit Mode *\\/\\r\\n.editmode-switch-form label {\\r\\n    color: #ffffff !important;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   COURSE CARDS\\r\\n   ========================================== *\\/\\r\\n\\r\\n.coursebox,\\r\\n.card,\\r\\n.block {\\r\\n    border-radius: 12px;\\r\\n    border: none !important;\\r\\n    box-shadow: 0 4px 12px rgba(0,0,0,.08);\\r\\n    background: #ffffff;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   HEADINGS\\r\\n   ========================================== *\\/\\r\\n\\r\\nh1 {\\r\\n    color: #0F4C81 !important;\\r\\n    font-weight: 700;\\r\\n}\\r\\n\\r\\nh2 {\\r\\n    color: #1D70B8 !important;\\r\\n    font-weight: 600;\\r\\n}\\r\\n\\r\\nh3 {\\r\\n    color: #0F4C81 !important;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   LINKS\\r\\n   ========================================== *\\/\\r\\n\\r\\na {\\r\\n    color: #1D70B8;\\r\\n}\\r\\n\\r\\na:hover {\\r\\n    color: #0F4C81;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   BUTTONS\\r\\n   ========================================== *\\/\\r\\n\\r\\n.btn-primary {\\r\\n    background: #0F4C81 !important;\\r\\n    border-color: #0F4C81 !important;\\r\\n    border-radius: 8px;\\r\\n}\\r\\n\\r\\n.btn-primary:hover {\\r\\n    background: #1D70B8 !important;\\r\\n    border-color: #1D70B8 !important;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   DASHBOARD BLOCKS\\r\\n   ========================================== *\\/\\r\\n\\r\\n.block {\\r\\n    padding: 10px;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   SITE ADMINISTRATION PAGE FIX\\r\\n   ========================================== *\\/\\r\\n\\r\\n#page-admin-index .card,\\r\\n.path-admin .card {\\r\\n    background: #ffffff !important;\\r\\n    color: #0F4C81 !important;\\r\\n    border-radius: 12px;\\r\\n}\\r\\n\\r\\n\\/* Administration Category Titles *\\/\\r\\n#page-admin-index .category,\\r\\n#page-admin-index .card-title,\\r\\n.path-admin .card-title {\\r\\n    color: #0F4C81 !important;\\r\\n    font-weight: 600 !important;\\r\\n}\\r\\n\\r\\n\\/* Administration Links *\\/\\r\\n#page-admin-index a,\\r\\n.path-admin a {\\r\\n    color: #1D70B8 !important;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   ACTIVITY SECTIONS\\r\\n   ========================================== *\\/\\r\\n\\r\\n.activity-item {\\r\\n    margin-bottom: 15px;\\r\\n    padding: 15px;\\r\\n    border-radius: 10px;\\r\\n    background: #ffffff;\\r\\n    border: 1px solid #e5e7eb;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   TABLES\\r\\n   ========================================== *\\/\\r\\n\\r\\n.generaltable {\\r\\n    border-radius: 8px;\\r\\n    overflow: hidden;\\r\\n}\\r\\n\\r\\n.generaltable th {\\r\\n    background: #0F4C81 !important;\\r\\n    color: white !important;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   FOOTER\\r\\n   ========================================== *\\/\\r\\n\\r\\n#page-footer {\\r\\n    background: #0F4C81;\\r\\n    color: #ffffff;\\r\\n    padding: 15px;\\r\\n}\\r\\n\\r\\n\\/* ==========================================\\r\\n   CUSTOM HOMEPAGE BANNER\\r\\n   ========================================== *\\/\\r\\n\\r\\n.vk-banner {\\r\\n    background: linear-gradient(135deg,#0F4C81,#1D70B8);\\r\\n    color: white;\\r\\n    padding: 50px;\\r\\n    border-radius: 16px;\\r\\n    text-align: center;\\r\\n    margin-bottom: 20px;\\r\\n}\\r\\n\\r\\n.vk-banner h1 {\\r\\n    color: #ffffff !important;\\r\\n}\\r\\n\\r\\n.vk-banner p {\\r\\n    color: #ffffff !important;\\r\\n    font-size: 18px;\\r\\n}\\r\\n\\/* Existing VKollab Theme CSS *\