INSERT INTO `mdl_page` (`id`, `course`, `name`, `intro`, `introformat`, `content`, `contentformat`, `legacyfiles`, `legacyfileslast`, `display`, `displayoptions`, `revision`, `timemodified`) VALUES
(1, 2, 'Information Security Basics', '<div>This page introduces the key concepts of Information Security, including data protection, password security, phishing awareness, and employee security responsibilities.</div>', 1, '<p><img class=\"img-fluid\" src=\"@@PLUGINFILE@@/image.png\"></p>', 1, 0, NULL, 5, 'a:2:{s:10:\"printintro\";s:1:\"0\";s:17:\"printlastmodified\";s:1:\"1\";}', 1, 1792598313),
(2, 2, 'Code of Conduct & Compilance', '<p>This page provides an overview of VKollab\'s Code of Conduct, workplace ethics, compliance expectations, and employee responsibilities.</p>', 1, '<p><img class=\"img-fluid\" src=\"@@PLUGINFILE@@/image.png\"></p>', 1, 0, NULL, 5, 'a:2:{s:10:\"printintro\";s:1:\"0\";s:17:\"printlastmodified\";s:1:\"1\";}', 1, 1792604499),
(3, 3, 'Introduction to Power Automate', '<div>This section introduces Microsoft Power Automate, its purpose, benefits, and key automation concepts.</div>\r\n<div> </div>', 1, '<p><img class=\"img-fluid\" src=\"@@PLUGINFILE@@/image.png\"></p>', 1, 0, NULL, 5, 'a:2:{s:10:\"printintro\";s:1:\"0\";s:17:\"printlastmodified\";s:1:\"1\";}', 3, 1793226184),
(4, 3, 'Core concepts', '<div>This section introduces the fundamental concepts of Power Automate including Flows, Triggers, Actions, Connectors, and Approvals.</div>', 1, '<p><img class=\"img-fluid\" src=\"@@PLUGINFILE@@/image.png\"></p>', 1, 0, NULL, 5, 'a:2:{s:10:\"printintro\";s:1:\"0\";s:17:\"printlastmodified\";s:1:\"1\";}', 3, 1793226198),
(5, 3, 'Power automate flow', '<div>Learn how to create a simple automated flow in Microsoft Power Automate using triggers and actions.</div>', 1, '<p><img class=\"img-fluid\" src=\"@@PLUGINFILE@@/image.png\"></p>', 1, 0, NULL, 5, 'a:2:{s:10:\"printintro\";s:1:\"0\";s:17:\"printlastmodified\";s:1:\"1\";}', 5, 1793226236),
(6, 5, 'Course Approval Request', '<div>Approval request for SAP CPI course.</div>', 1, '<div>Course Name: SAP CPI</div>\r\n<div> </div>\r\n<div>Created By: Moulika Ramisetty</div>\r\n<div>Role: Practice Manager</div>\r\n<div> </div>\r\n<div>Submission Date: 23-Oct-2026</div>\r\n<div> </div>\r\n<div>Status: Pending Director Approval</div>\r\n<div> </div>\r\n<div>Requested Approver: Venkat Makke (CEO/Director)</div>\r\n<div> </div>\r\n<div>Comments:</div>\r\n<div>Course content and assessment are ready for review and approval.</div>', 1, 0, NULL, 5, 'a:2:{s:10:\"printintro\";s:1:\"0\";s:17:\"printlastmodified\";s:1:\"1\";}', 1, 1792764762);
