(1, 0, 'Q1 - Importance of Information Security', '<div>Why is information security important?</div>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'localhost+261021174839+a6mbF0', 1792604919, 1792604919, 2, 2),
(2, 0, 'Q2 - Password Security', '<div>Which of the following is a good password practice?</div>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'localhost+261021175024+PeU0Wh', 1792605024, 1792605024, 2, 2),
(3, 0, 'Q3 - Suspicious Email', '<div>What should you do if you receive a suspicious email?</div>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'localhost+261021175213+6t0wqj', 1792605133, 1792605133, 2, 2),
