(5, 0, 'Q5 - Compliance Training', '<div>What is the primary purpose of compliance training?</div>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'localhost+261021175417+jWFZZi', 1792605257, 1792605257, 2, 2),
(6, 0, 'Q1 - Power Automate Purpose', '<div>What is the primary purpose of Microsoft Power Automate?</div>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'localhost+261021181641+eoVv4x', 1792606601, 1792606601, 2, 2),
(7, 0, 'Q1 - Power Automate Purpose', '<div>What is the primary purpose of Microsoft Power Automate?</div>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'localhost+261021181649+qTsZ1E', 1792606609, 1792606609, 2, 2),
(8, 0, 'Q2 - Trigger', '<div>What starts a Flow in Power Automate?</div>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'localhost+261021181822+wASAsb', 1792606702, 1792606702, 2, 2),
(9, 0, 'Q2 - Trigger', '<div>What starts a Flow in Power Automate?</div>', 1, '', 1, 1.0000000, 0.3333333, 'multichoice', 1, 'localhost+261021181829+quMVMr', 1792606709, 1792606709, 2, 2),
(10, 0, 'Q3 - Email Security', '<div>Suspicious emails should be reported to the IT/Security Team instead of opening attachments or clicking unknown links.</div>', 1, '', 1, 1.0000000, 1.0000000, 'truefalse', 1, 'localhost+261021182032+R1ieWv', 1792606832, 1792606832, 2, 2),
(11, 0, 'Q4 - Flow Trigger', '<div>What starts a Flow in Microsoft Power Automate?</div>', 1, '', 1, 1.0000000, 0.3333333, 'shortanswer', 1, 'localhost+261021182204+Ju04D6', 1792606924, 1792606924, 2, 2),
(12, 0, 'Automation Benefits', '<div>Describe one real-world business process that can be automated using Microsoft Power Automate and explain its benefits.</div>', 1, '', 1, 5.0000000, 0.0000000, 'essay', 1, 'localhost+261021182528+PWB4pj', 1792607128, 1792607128, 2, 2);
