INSERT INTO `mdl_quiz` (`id`, `course`, `name`, `intro`, `introformat`, `timeopen`, `timeclose`, `timelimit`, `overduehandling`, `graceperiod`, `preferredbehaviour`, `canredoquestions`, `attempts`, `attemptonlast`, `grademethod`, `decimalpoints`, `questiondecimalpoints`, `reviewattempt`, `reviewcorrectness`, `reviewmaxmarks`, `reviewmarks`, `reviewspecificfeedback`, `reviewgeneralfeedback`, `reviewrightanswer`, `reviewoverallfeedback`, `questionsperpage`, `navmethod`, `shuffleanswers`, `sumgrades`, `grade`, `timecreated`, `timemodified`, `password`, `subnet`, `browsersecurity`, `delay1`, `delay2`, `showuserpicture`, `showblocks`, `completionattemptsexhausted`, `completionminattempts`, `allowofflineattempts`) VALUES
(1, 2, 'Email Ettiquate Assessment', '<div>This assessment evaluates your understanding of information security practices, workplace ethics, compliance requirements, and employee responsibilities covered in this course.</div>\r\n<div> </div>\r\n<div>Instructions:</div>\r\n<div>• Read each question carefully.</div>\r\n<div>• Select the most appropriate answer.</div>\r\n<div>• A minimum score of 70% is recommended for successful completion.</div>', 1, 0, 0, 600, 'autosubmit', 0, 'deferredfeedback', 0, 1, 0, 1, 2, -1, 69888, 4352, 69888, 4352, 4352, 4352, 4352, 4352, 1, 'free', 1, 5.00000, 10.00000, 1792604637, 1792696949, '', '', '-', 0, 0, 0, 0, 1, 1, 0),
(2, 3, 'Power Automate Fundamentals Assessment', '<div>This assessment evaluates your understanding of Microsoft Power Automate concepts, including flows, triggers, actions, connectors, and automation best practices.</div>\r\n<div> </div>\r\n<div>Instructions:</div>\r\n<div>• Read each question carefully.</div>\r\n<div>• Select the most appropriate answer.</div>\r\n<div>• Complete all questions before submitting.</div>\r\n<div>• Passing score: 70%.</div>', 1, 0, 0, 300, 'autosubmit', 0, 'deferredfeedback', 0, 0, 0, 1, 2, -1, 69888, 4352, 69888, 4352, 4352, 4352, 4352, 4352, 1, 'free', 1, 9.00000, 10.00000, 1792606524, 1792866069, '', '', '-', 0, 0, 0, 0, 0, 0, 0);
